int CDECL system(const char* cmd)
{
  int res = -1;
  wchar_t *cmdW;

  if (cmd == NULL)
    return _wsystem(NULL);

  if ((cmdW = wstrdupa_utf8(cmd)))
  {
    res = _wsystem(cmdW);
    free(cmdW);
  }
  return res;
}

